-- Migration: 0030_services_catalogue
-- Roadmap: Phase 31 (§ 11A) — Services, About, Contact & Start.
--
-- 31.1 Services by kind of software. Five services replace the seven of
--      revisions 1–44: websites · web systems & admin panels · mobile apps ·
--      desktop software · support & extension — each with what you get, its
--      process in four steps and its questions, in the customer's words (§ 16).
--      Same content as the seed `lib/services-content.ts` (the block between
--      the markers is generated from it by `scripts/import-content-to-db.ts
--      --sql`). No "from" price is set: the owner sets one in the admin (D-04).
--      The seven old services are unpublished, not deleted — old requests keep
--      their reference and the owner can still read them in the admin.
-- 31.2 "How working together goes": payment, ownership, handover, changes and
--      after launch, as global FAQs (Content → Global FAQs) shown on /services.
--      /process is retired (redirected to /services#process in next.config.mjs),
--      so its menu item is removed.
--
-- ROLLBACK:
--   delete from public.services where slug in ('websites', 'web-systems', 'mobile-apps', 'desktop-software', 'support');
--   update public.services set published = true, sort_order = sort_order - 100
--     where slug in ('business-website', 'web-application-mvp', 'admin-dashboards', 'backend-api-database',
--                    'performance-accessibility-seo', 'bug-fix-rescue', 'care-plan') and sort_order >= 100;
--   delete from public.faqs where scope = 'global' and question->>'en' in ('How does payment work?', 'Who owns the software?',
--     'What do we receive at handover?', 'What if we want changes along the way?', 'What happens after launch?');
--   insert into public.navigation_items (key, href, surfaces, has_description, has_content, sort_order)
--     values ('process', '/process', '{footer,command-palette}', true, true, 4);

-- 31.1 the old catalogue leaves the site
update public.services
  set published = false, sort_order = sort_order + 100
  where slug in ('business-website', 'web-application-mvp', 'admin-dashboards', 'backend-api-database',
                 'performance-accessibility-seo', 'bug-fix-rescue', 'care-plan')
    and sort_order < 100;

-- 31.1 the new catalogue — generated from lib/services-content.ts (begin)
