insert into public.services (slug, icon, title, description, deliverables, type, tagline, for_whom, not_for_whom, problem, what_i_do, included, not_included, timeline, requirements, related_project_slugs, what_drives_cost, payment_schedule_note, published, sort_order, kind, show_packages)
values ('websites', 'Globe', '{"en":"Business websites","fa":"وب‌سایت برای کسب‌وکار"}'::jsonb, '{"en":"A website that presents your business and brings in customers.","fa":"وب‌سایتی که کسب‌وکار شما را معرفی می‌کند و مشتری می‌آورد."}'::jsonb, '[{"en":"Designed in your brand’s colours and style","fa":"طراحی با رنگ‌ها و نشان کسب‌وکار شما"},{"en":"Works well on phone, tablet and computer","fa":"روی موبایل، تبلت و کمپیوتر به‌خوبی کار می‌کند"},{"en":"A panel to update pages, news and photos yourself","fa":"پنلی که صفحه‌ها، خبرها و عکس‌ها را خودتان در آن به‌روز می‌کنید"},{"en":"Contact form and a WhatsApp button","fa":"فورم تماس و دکمه‌ی واتس‌اپ"},{"en":"Set up so customers find you on Google","fa":"تنظیم‌شده تا مشتریان شما را در گوگل پیدا کنند"},{"en":"In the languages your customers read","fa":"به زبان‌هایی که مشتریان شما می‌خوانند"}]'::jsonb, null, '{"en":"A fast, good-looking website your customers find and trust — and your staff keep up to date themselves.","fa":"وب‌سایتی زیبا و سریع که مشتریان شما آن را پیدا می‌کنند و به آن اعتماد می‌کنند؛ کارمندان شما هم خودشان آن را به‌روز نگه می‌دارند."}'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, ARRAY['pazhuhesh-portal']::text[], '[]'::jsonb, null, true, 0, 'website', false)
