  ((select id from public.services where slug = 'websites'), '{"en":"Design","fa":"طراحی"}'::jsonb, '{"en":"You see the pages and approve them before they are built.","fa":"صفحه‌ها را پیش از ساخت می‌بینید و تأیید می‌کنید."}'::jsonb, 1),
  ((select id from public.services where slug = 'websites'), '{"en":"Build","fa":"ساخت"}'::jsonb, '{"en":"The site is built and your texts and photos go in.","fa":"وب‌سایت ساخته می‌شود و متن‌ها و عکس‌های شما در آن قرار می‌گیرد."}'::jsonb, 2),
  ((select id from public.services where slug = 'websites'), '{"en":"Launch and support","fa":"راه‌اندازی و پشتیبانی"}'::jsonb, '{"en":"The site goes live, and Artaveo stays with you after launch.","fa":"وب‌سایت روی انترنت می‌رود و آرتاویو بعد از راه‌اندازی هم در کنار شماست."}'::jsonb, 3);
