insert into public.faqs (scope, service_id, question, answer, sort_order) values
  ('service', (select id from public.services where slug = 'websites'), '{"en":"How long does a website take?","fa":"ساخت یک وب‌سایت چقدر وقت می‌گیرد؟"}'::jsonb, '{"en":"It depends on the number of pages and how ready your texts and photos are. You get a clear timeline after the first conversation.","fa":"به تعداد صفحه‌ها و آماده‌بودن متن‌ها و عکس‌های شما بستگی دارد. بعد از گفتگوی اول، زمان‌بندی روشن را دریافت می‌کنید."}'::jsonb, 0),
  ('service', (select id from public.services where slug = 'websites'), '{"en":"Can we update the site ourselves?","fa":"آیا خودمان می‌توانیم وب‌سایت را به‌روز کنیم؟"}'::jsonb, '{"en":"Yes. You get a simple panel to change texts, photos and news whenever you like.","fa":"بلی. یک پنل ساده دارید که متن‌ها، عکس‌ها و خبرها را هر وقت خواستید در آن تغییر می‌دهید."}'::jsonb, 1);

