values ('web-systems', 'PanelsTopLeft', '{"en":"Web systems & admin panels","fa":"سیستم‌های تحت وب و پنل مدیریت"}'::jsonb, '{"en":"Management systems your staff use every day, from any computer or phone.","fa":"سیستم‌های مدیریتی که کارمندان شما هر روز از هر کمپیوتر یا موبایل با آن کار می‌کنند."}'::jsonb, '[{"en":"Built around the way your business works","fa":"مطابق روش کار کسب‌وکار شما ساخته می‌شود"},{"en":"Separate access for managers, staff and customers","fa":"دسترسی جدا برای مدیر، کارمند و مشتری"},{"en":"Online sales, bookings and tickets where you need them","fa":"فروش، ثبت و تکت آنلاین هر جا که ضرورت دارید"},{"en":"Reports you can print or download in Excel","fa":"گزارش‌هایی که چاپ می‌کنید یا در اکسل می‌گیرید"},{"en":"Works on phone and computer","fa":"روی موبایل و کمپیوتر کار می‌کند"},{"en":"Training for your staff and support after launch","fa":"آموزش کارمندان و پشتیبانی بعد از راه‌اندازی"}]'::jsonb, null, '{"en":"Sales, bookings, tickets, stock, students or customers — run your daily work in one system and get a report whenever you need one.","fa":"فروش، ثبت‌نام، تکت، گدام، محصلان یا مشتریان؛ کار روزمره‌ی خود را در یک سیستم پیش ببرید و هر وقت خواستید گزارش بگیرید."}'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, ARRAY['transportation-system', 'pazhuhesh-portal']::text[], '[]'::jsonb, null, true, 1, 'web-system', false)
