  ('service', (select id from public.services where slug = 'web-systems'), '{"en":"Can our current records move into the new system?","fa":"آیا معلومات فعلی ما به سیستم تازه منتقل می‌شود؟"}'::jsonb, '{"en":"Yes. Lists you keep in Excel or another program are moved in, so you start with your own records.","fa":"بلی. فهرست‌هایی که در اکسل یا برنامه‌ی دیگری دارید به سیستم تازه منتقل می‌شوند و کار را با معلومات خودتان شروع می‌کنید."}'::jsonb, 0),
  ('service', (select id from public.services where slug = 'web-systems'), '{"en":"Can new parts be added later?","fa":"آیا بعداً می‌شود بخش تازه‌ای اضافه کرد؟"}'::jsonb, '{"en":"Yes. Whenever your business needs a new part, Artaveo adds it to the same system.","fa":"بلی. هر وقت کسب‌وکار شما به بخش تازه‌ای ضرورت داشت، آرتاویو آن را به همان سیستم اضافه می‌کند."}'::jsonb, 1);

