values ('mobile-apps', 'Smartphone', '{"en":"Mobile apps","fa":"اپلیکیشن موبایل"}'::jsonb, '{"en":"Apps for Android and iPhone that your customers and staff carry with them.","fa":"اپلیکیشن برای اندروید و آیفون که مشتریان و کارمندان شما همیشه همراه دارند."}'::jsonb, '[{"en":"For Android and iPhone","fa":"برای اندروید و آیفون"},{"en":"A design that feels natural on a phone","fa":"طراحی‌ای که روی موبایل راحت و آشناست"},{"en":"Messages and alerts for your customers","fa":"پیام و اطلاع‌رسانی برای مشتریان"},{"en":"Works together with your website and admin panel","fa":"هماهنگ با وب‌سایت و پنل مدیریت شما"},{"en":"Published on Google Play and the App Store","fa":"نشر در گوگل پلی و اپ استور"},{"en":"Updates and support after launch","fa":"به‌روزرسانی و پشتیبانی بعد از راه‌اندازی"}]'::jsonb, null, '{"en":"Put your service in your customers’ pockets — sign-ups, purchases, bookings and messages in one app.","fa":"خدمات خود را به موبایل مشتریان ببرید؛ ثبت‌نام، خرید، وقت‌گرفتن و پیام‌ها در یک اپلیکیشن."}'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, '{}'::text[], '[]'::jsonb, null, true, 2, 'mobile-app', false)
