  ((select id from public.services where slug = 'mobile-apps'), '{"en":"A conversation","fa":"گفتگو"}'::jsonb, '{"en":"About who will use the app and what they should be able to do.","fa":"درباره‌ی این‌که چه کسانی از اپلیکیشن استفاده می‌کنند و چه کاری باید بتوانند انجام دهند."}'::jsonb, 0),
