  ((select id from public.services where slug = 'mobile-apps'), '{"en":"Build","fa":"ساخت"}'::jsonb, '{"en":"You install test versions and follow the progress.","fa":"نسخه‌های آزمایشی را نصب می‌کنید و پیشرفت کار را می‌بینید."}'::jsonb, 2),
