insert into public.faqs (scope, service_id, question, answer, sort_order) values
  ('service', (select id from public.services where slug = 'mobile-apps'), '{"en":"Do we need both Android and iPhone?","fa":"آیا به هر دو، اندروید و آیفون، ضرورت داریم؟"}'::jsonb, '{"en":"Not always. In the first conversation you look together at where your customers are; the app can start on one and add the other later.","fa":"همیشه نه. در گفتگوی اول با هم می‌بینیم مشتریان شما بیشتر از کدام استفاده می‌کنند؛ اپلیکیشن می‌تواند با یکی شروع شود و دیگری بعداً اضافه شود."}'::jsonb, 0),
  ('service', (select id from public.services where slug = 'mobile-apps'), '{"en":"Can the app work without internet?","fa":"آیا اپلیکیشن بدون انترنت هم کار می‌کند؟"}'::jsonb, '{"en":"Yes, where your work needs it: the app keeps working offline and sends everything once the connection is back.","fa":"بلی، هر جا کار شما ضرورت داشته باشد: اپلیکیشن بدون انترنت هم کار می‌کند و وقتی انترنت وصل شد، همه‌چیز را می‌فرستد."}'::jsonb, 1);

