values ('desktop-software', 'Monitor', '{"en":"Desktop software","fa":"نرم‌افزار کمپیوتری"}'::jsonb, '{"en":"Programs for Windows and Mac that run in your office — with or without internet.","fa":"برنامه برای ویندوز و مک که در دفتر شما کار می‌کند؛ با انترنت یا بدون آن."}'::jsonb, '[{"en":"For Windows and Mac","fa":"برای ویندوز و مک"},{"en":"Works without internet","fa":"بدون انترنت کار می‌کند"},{"en":"Several computers working on the same records","fa":"چند کمپیوتر روی یک معلومات مشترک کار می‌کنند"},{"en":"Printed receipts and reports","fa":"چاپ رسید و گزارش"},{"en":"Stays in step with your online system when connected","fa":"وقتی انترنت وصل شد، با سیستم آنلاین شما هماهنگ می‌شود"},{"en":"Installation, training and support","fa":"نصب، آموزش و پشتیبانی"}]'::jsonb, null, '{"en":"Software for the office, the shop or the clinic that keeps working even when the internet does not.","fa":"نرم‌افزاری برای دفتر، دکان یا کلینیک که حتی وقتی انترنت قطع است، کار شما را متوقف نمی‌کند."}'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, ARRAY['artaveo-dental']::text[], '[]'::jsonb, null, true, 3, 'desktop-software', false)
