insert into public.faqs (scope, service_id, question, answer, sort_order) values
  ('service', (select id from public.services where slug = 'desktop-software'), '{"en":"What happens when the internet goes down?","fa":"اگر انترنت قطع شود چه می‌شود؟"}'::jsonb, '{"en":"Nothing stops. Work carries on at the computer, and everything is shared once the connection is back.","fa":"کار متوقف نمی‌شود. کار روی کمپیوتر ادامه پیدا می‌کند و وقتی انترنت وصل شد، همه‌چیز هماهنگ می‌شود."}'::jsonb, 0),
  ('service', (select id from public.services where slug = 'desktop-software'), '{"en":"Can it run on several computers?","fa":"آیا روی چند کمپیوتر کار می‌کند؟"}'::jsonb, '{"en":"Yes. Several computers in your office can work on the same records at the same time.","fa":"بلی. چند کمپیوتر در دفتر شما می‌توانند هم‌زمان روی یک معلومات مشترک کار کنند."}'::jsonb, 1);

-- service: support
insert into public.services (slug, icon, title, description, deliverables, type, tagline, for_whom, not_for_whom, problem, what_i_do, included, not_included, timeline, requirements, related_project_slugs, what_drives_cost, payment_schedule_note, published, sort_order, kind, show_packages)
values ('support', 'Wrench', '{"en":"Support & extension","fa":"پشتیبانی و توسعه"}'::jsonb, '{"en":"Keep your software running and add what it is missing.","fa":"نرم‌افزار شما را سرپا نگه می‌دارد و آنچه کم دارد را اضافه می‌کند."}'::jsonb, '[{"en":"Problems in your current software fixed","fa":"رفع مشکل‌های نرم‌افزار فعلی شما"},{"en":"New features and pages","fa":"بخش‌ها و صفحه‌های تازه"},{"en":"Faster pages and a fresher look","fa":"صفحه‌های سریع‌تر و ظاهر تازه‌تر"},{"en":"Regular updates","fa":"به‌روزرسانی منظم"},{"en":"Monthly or yearly support","fa":"پشتیبانی ماهانه یا سالانه"},{"en":"A reply the same day when something goes wrong","fa":"جواب در همان روز، وقتی مشکلی پیش آید"}]'::jsonb, null, '{"en":"For software you already have, whoever built it: fixes, new features, updates and help whenever you need it.","fa":"برای نرم‌افزاری که همین حالا دارید، هر کسی آن را ساخته باشد: رفع مشکل، بخش‌های تازه، به‌روزرسانی و کمک هر وقت ضرورت داشتید."}'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '[]'::jsonb, '{}'::text[], '[]'::jsonb, null, true, 4, 'support', false)
on conflict (slug) do update set icon=excluded.icon, title=excluded.title, description=excluded.description, deliverables=excluded.deliverables, type=excluded.type, tagline=excluded.tagline, for_whom=excluded.for_whom, not_for_whom=excluded.not_for_whom, problem=excluded.problem, what_i_do=excluded.what_i_do, included=excluded.included, not_included=excluded.not_included, timeline=excluded.timeline, requirements=excluded.requirements, related_project_slugs=excluded.related_project_slugs, what_drives_cost=excluded.what_drives_cost, payment_schedule_note=excluded.payment_schedule_note, published=excluded.published, sort_order=excluded.sort_order, kind=excluded.kind, show_packages=excluded.show_packages, updated_at=now();
delete from public.service_process_steps where service_id = (select id from public.services where slug = 'support');
insert into public.service_process_steps (service_id, title, description, sort_order) values
  ((select id from public.services where slug = 'support'), '{"en":"A conversation","fa":"گفتگو"}'::jsonb, '{"en":"You describe what is wrong or what is missing.","fa":"مشکل یا کمبود نرم‌افزار را برای آرتاویو توضیح می‌دهید."}'::jsonb, 0),
  ((select id from public.services where slug = 'support'), '{"en":"A review","fa":"بررسی"}'::jsonb, '{"en":"Artaveo looks at your software and tells you what it takes.","fa":"آرتاویو نرم‌افزار شما را بررسی می‌کند و می‌گوید چه کاری لازم است."}'::jsonb, 1),
  ((select id from public.services where slug = 'support'), '{"en":"The work","fa":"انجام کار"}'::jsonb, '{"en":"Fixes and new parts are done, and you check them.","fa":"مشکل‌ها رفع و بخش‌های تازه اضافه می‌شوند و شما آن‌ها را بررسی می‌کنید."}'::jsonb, 2),
  ((select id from public.services where slug = 'support'), '{"en":"Ongoing support","fa":"پشتیبانی دوامدار"}'::jsonb, '{"en":"Monthly or yearly, as you choose.","fa":"ماهانه یا سالانه، هر طور که شما بخواهید."}'::jsonb, 3);
delete from public.service_addons where service_id = (select id from public.services where slug = 'support');
delete from public.faqs where scope = 'service' and service_id = (select id from public.services where slug = 'support');
insert into public.faqs (scope, service_id, question, answer, sort_order) values
  ('service', (select id from public.services where slug = 'support'), '{"en":"Artaveo did not build our software. Can it still help?","fa":"نرم‌افزار ما را آرتاویو نساخته است. باز هم کمک می‌کند؟"}'::jsonb, '{"en":"Yes. Artaveo reviews it first, then tells you what can be fixed and what can be added.","fa":"بلی. آرتاویو اول آن را بررسی می‌کند و بعد می‌گوید چه چیزهایی رفع و چه چیزهایی اضافه می‌شود."}'::jsonb, 0),
  ('service', (select id from public.services where slug = 'support'), '{"en":"How does monthly support work?","fa":"پشتیبانی ماهانه چطور است؟"}'::jsonb, '{"en":"You agree on what it covers — updates, small changes, help — and pay monthly or yearly.","fa":"روی آنچه شامل آن است توافق می‌کنید (به‌روزرسانی، تغییرهای کوچک و کمک) و پول آن را ماهانه یا سالانه می‌پردازید."}'::jsonb, 1);

-- 31.1 the new catalogue (end)

-- 31.2 how working together goes
insert into public.faqs (scope, service_id, question, answer, sort_order)
  select 'global', null, '{"en": "How does payment work?", "fa": "پرداخت چطور انجام می‌شود؟"}'::jsonb, '{"en": "In parts, as the work moves forward: a first part when it starts and the rest at the stages you agree on. The exact split is written into your agreement.", "fa": "به‌مرور و همراه با پیشرفت کار: یک بخش در شروع و باقی آن در مرحله‌هایی که با هم توافق می‌کنید. تقسیم دقیق آن در قرارداد شما نوشته می‌شود."}'::jsonb, 0
  where not exists (select 1 from public.faqs where scope = 'global' and question->>'en' = 'How does payment work?');
insert into public.faqs (scope, service_id, question, answer, sort_order)
  select 'global', null, '{"en": "Who owns the software?", "fa": "نرم‌افزار مال کیست؟"}'::jsonb, '{"en": "Software built for you is yours once it is paid for, with its content and records, and accounts such as the domain and hosting are opened in your name. For Artaveo’s ready-made products, what you get is written on the product page and in its agreement.", "fa": "نرم‌افزاری که برای شما ساخته می‌شود، بعد از پرداخت کامل مال شماست؛ همراه با محتوا و معلومات آن. حساب‌هایی مثل دامنه و هاست هم به نام خود شما باز می‌شوند. برای محصولات آماده‌ی آرتاویو، آنچه می‌گیرید در صفحه‌ی همان محصول و قرارداد آن نوشته شده است."}'::jsonb, 1
  where not exists (select 1 from public.faqs where scope = 'global' and question->>'en' = 'Who owns the software?');
insert into public.faqs (scope, service_id, question, answer, sort_order)
  select 'global', null, '{"en": "What do we receive at handover?", "fa": "در تحویل چه چیزی دریافت می‌کنیم؟"}'::jsonb, '{"en": "Working software, access to every part of it, and training for your staff.", "fa": "نرم‌افزاری که کار می‌کند، دسترسی به همه‌ی بخش‌های آن و آموزش کارمندان شما."}'::jsonb, 2
  where not exists (select 1 from public.faqs where scope = 'global' and question->>'en' = 'What do we receive at handover?');
insert into public.faqs (scope, service_id, question, answer, sort_order)
  select 'global', null, '{"en": "What if we want changes along the way?", "fa": "اگر در میانه‌ی کار تغییری بخواهیم چه؟"}'::jsonb, '{"en": "Tell Artaveo. Small changes are made as the work goes on; larger ones are priced and agreed with you before they are built.", "fa": "به آرتاویو بگویید. تغییرهای کوچک در جریان کار انجام می‌شوند و تغییرهای بزرگ‌تر پیش از ساخت، قیمت‌گذاری و با شما توافق می‌شوند."}'::jsonb, 3
  where not exists (select 1 from public.faqs where scope = 'global' and question->>'en' = 'What if we want changes along the way?');
insert into public.faqs (scope, service_id, question, answer, sort_order)
  select 'global', null, '{"en": "What happens after launch?", "fa": "بعد از راه‌اندازی چه می‌شود؟"}'::jsonb, '{"en": "Problems found after delivery are fixed within the period written into your agreement. After that, you can carry on with monthly or yearly support.", "fa": "مشکل‌هایی که بعد از تحویل پیدا شوند، در مدتی که در قرارداد شما نوشته شده رفع می‌شوند. بعد از آن می‌توانید با پشتیبانی ماهانه یا سالانه ادامه دهید."}'::jsonb, 4
  where not exists (select 1 from public.faqs where scope = 'global' and question->>'en' = 'What happens after launch?');

